CREATE TABLE controlplane.cp_command_receipts (receipt_id UUID PRIMARY KEY, workspace_id UUID NOT NULL REFERENCES controlplane.cp_workspaces(workspace_id), command_id TEXT NOT NULL, disposition TEXT NOT NULL CHECK (disposition IN ('accepted','rejected')), operation_id UUID NULL, resource_ref JSONB NULL, accepted_at TIMESTAMPTZ NOT NULL, current_revision BIGINT NULL, UNIQUE (workspace_id, command_id), UNIQUE (workspace_id, receipt_id));
CREATE TABLE controlplane.cp_idempotency_records (workspace_id UUID NOT NULL, command_name TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, receipt_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NULL, PRIMARY KEY (workspace_id, command_name, idempotency_key), FOREIGN KEY (workspace_id, receipt_id) REFERENCES controlplane.cp_command_receipts(workspace_id, receipt_id));
